@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
    email: String,
    vm: HomeViewModel,
    onSignOut: () -> Unit,
    onNavigateToNewTrip: () -> Unit,
    onNavigateToMyTrips: () -> Unit,
    onNavigateToAbout: () -> Unit,
    onNavigateToPhotos: (tripId: Long, destination: String) -> Unit,
